# Compare the OpenLSTO Julia stress-minimization port against the reference
# C++ OpenLSTO output.
#
# The reference (test/OpenLSTO/reference_stress_40x40.txt) is generated by
# `stress_driver.cpp`, which reproduces the OpenLSTO L-beam stress problem
# (`projects/stress_min/lbeam.cpp`) on a 40x40 mesh with the five radius-4
# holes. The level-set method is chaotic in the sense that tiny floating-point
# differences (the CG solver, least-squares solve) accumulate into growing
# trajectory differences after a few iterations, so the first iteration is
# compared tightly and the final result loosely.

using Test
using LinearAlgebra, SparseArrays, Random
using TopOpt

const L = TopOpt.OpenLSTO

# The five-hole L-beam seeding of `stress_minimization` scaled to 40x40 (the
# `lbeam.cpp` holes of radius 10 on 100x100, scaled by 2/5).
const HOLES = L.LevelSetHole[
    L.LevelSetHole(8, 8, 4),
    L.LevelSetHole(8, 20, 4),
    L.LevelSetHole(8, 32, 4),
    L.LevelSetHole(20, 8, 4),
    L.LevelSetHole(32, 8, 4),
]

function read_stress_reference(path::AbstractString)
    iterations = Int[]
    objectives = Float64[]
    von_mises = Float64[]
    areas = Float64[]
    for line in eachline(path)
        tokens = split(line)
        length(tokens) == 4 || continue
        push!(iterations, parse(Int, tokens[1]))
        push!(objectives, parse(Float64, tokens[2]))
        push!(von_mises, parse(Float64, tokens[3]))
        push!(areas, parse(Float64, tokens[4]))
    end
    return iterations, objectives, von_mises, areas
end

@testset "OpenLSTO stress reference" begin
    reference = get(
        ENV, "OPENLSTO_STRESS_REFERENCE", joinpath(@__DIR__, "reference_stress_40x40.txt")
    )
    ref_iters, ref_objective, ref_vm, ref_area = read_stress_reference(reference)
    @test !isempty(ref_iters)

    result = L.stress_minimization(;
        nelx=40, nely=40, holes=HOLES, max_iterations=length(ref_iters), verbose=false
    )

    @test length(result.objectives) == length(ref_iters)
    @test length(result.areas) == length(ref_iters)

    # The first iteration is deterministic: it only depends on the initial
    # level set, which the port reproduces to machine precision. It exercises
    # the full stress path (the p-norm objective, the von Mises maximum, and
    # the adjoint-based sensitivities all depend on B_int and the two-node
    # load), so it catches port deviations like a missing quadrature factor.
    @test result.objectives[1] ≈ ref_objective[1] rtol = 1e-6
    @test result.areas[1] ≈ ref_area[1] atol = 1e-8

    # After many iterations the two trajectories drift apart (see the note
    # above), but both must end at a comparable design and stress level.
    @test result.objectives[end] ≈ ref_objective[end] rtol = 2e-2
    @test result.areas[end] ≈ ref_area[end] atol = 1e-2
    @test result.sensitivities.von_mises_max ≈ ref_vm[end] rtol = 2e-2
end
